cat << 'EOF' > fix_dups.mjs
import fs from 'fs';

let wsTestSupport = fs.readFileSync('src/transport/wsTestSupport.ts', 'utf8');
wsTestSupport = wsTestSupport.replace(
  'import type {SessionStore} from \'../types/sessionStore.js\';',
  'import type {SessionStore} from \'../types/sessionStore.js\';\nimport {InMemorySessionStore} from \'../infrastructure/stores/inMemorySessionStore.js\';'
);
wsTestSupport = wsTestSupport.replace(
  'import("../infrastructure/stores/inMemorySessionStore.js").InMemorySessionStore',
  'InMemorySessionStore'
);
// Also modify stopEngines to wait for clients.size === 0
wsTestSupport = wsTestSupport.replace(
  '  for (const hal of servers.splice(0)) await hal.stop();',
  '  for (const hal of servers.splice(0)) {\n    const {wss} = hal as any;\n    if (wss && wss.clients) { await eventually(() => wss.clients.size === 0); }\n    await hal.stop();\n  }'
);

fs.writeFileSync('src/transport/wsTestSupport.ts', wsTestSupport);

let resume = fs.readFileSync('src/transport/sessionResume.test.ts', 'utf8');
resume = resume.replace(
  'import {answeringOrchestrator} from \'./wsTestSupport.js\';',
  'import {answeringOrchestrator, eventually, delegatingStore} from \'./wsTestSupport.js\';'
);
// remove eventually
resume = resume.replace(/const _eventually = [^]*?};\n\n/m, '');
resume = resume.replace(/const eventually = [^]*?};\n\n/m, '');
// remove delegatingTo
resume = resume.replace(/\/\/ A store with only the required members.*?\nconst _delegatingTo = [^]*?}\);\n\n/m, '');
resume = resume.replace(/\/\/ A store with only the required members.*?\nconst delegatingTo = [^]*?}\);\n\n/m, '');
// change delegatingTo to delegatingStore
resume = resume.replace(/delegatingTo/g, 'delegatingStore');
// remove duplicate teardown in afterEach
resume = resume.replace(/  for \(const client of clients\.splice\(0\)\) client\.terminate\(\);\n  for \(const hal of servers\.splice\(0\)\) {\n    const {wss} = hal;\n    await eventually\(\(\) => wss\.clients\.size === 0\);\n    await hal\.stop\(\);\n  }/m, '  await stopEngines();');
// also import stopEngines in resume
resume = resume.replace(
  'import {answeringOrchestrator, eventually, delegatingStore}',
  'import {answeringOrchestrator, eventually, delegatingStore, stopEngines}'
);
fs.writeFileSync('src/transport/sessionResume.test.ts', resume);


let conv = fs.readFileSync('src/transport/conversationList.acceptance.test.ts', 'utf8');
conv = conv.replace(
  'import {answeringOrchestrator} from \'./wsTestSupport.js\';',
  'import {answeringOrchestrator, eventually, delegatingStore, stopEngines} from \'./wsTestSupport.js\';'
);
conv = conv.replace(/const eventually = [^]*?};\n\n/m, '');
conv = conv.replace(/\/\/ A store with only the five required members.*?\nconst delegatingTo = [^]*?}\);\n\n/m, '');
conv = conv.replace(/delegatingTo/g, 'delegatingStore');
conv = conv.replace(/  for \(const client of clients\.splice\(0\)\) client\.terminate\(\);\n  for \(const hal of servers\.splice\(0\)\) {\n    const {wss} = hal;\n    await eventually\(\(\) => wss\.clients\.size === 0\);\n    await hal\.stop\(\);\n  }/m, '  await stopEngines();');
fs.writeFileSync('src/transport/conversationList.acceptance.test.ts', conv);

EOF
node fix_dups.mjs

cat << 'EOF' > fix_resume.mjs
import fs from 'fs';

let content = fs.readFileSync('src/transport/sessionResume.test.ts', 'utf8');

// import helpers
content = content.replace(
  "import {answeringOrchestrator} from './wsTestSupport.js';",
  "import {answeringOrchestrator, eventually, delegatingStore, drainAndStop} from './wsTestSupport.js';"
);

// Remove eventually
content = content.replace(/const eventually = async[^]*?};\n\n/m, '');

// Replace afterEach
content = content.replace(
  /afterEach\(async \(\) => \{\n  for \(const client of clients\.splice\(0\)\) client\.terminate\(\);\n  for \(const hal of servers\.splice\(0\)\) \{\n    const \{wss\} = hal;\n    await eventually\(\(\) => wss\.clients\.size === 0\);\n    await hal\.stop\(\);\n  \}\n\}\);/m,
  'afterEach(async () => {\n  await drainAndStop(clients, servers);\n});'
);

// Remove delegatingTo and replace with delegatingStore
content = content.replace(/\/\/ A store with only the required members.*?\nconst delegatingTo = [^]*?}\);\n\n/m, '');
content = content.replace(/delegatingTo/g, 'delegatingStore');

fs.writeFileSync('src/transport/sessionResume.test.ts', content);

let conv = fs.readFileSync('src/transport/conversationList.acceptance.test.ts', 'utf8');

conv = conv.replace(
  "import {answeringOrchestrator} from './wsTestSupport.js';",
  "import {answeringOrchestrator, eventually, delegatingStore, drainAndStop} from './wsTestSupport.js';"
);

conv = conv.replace(/const eventually = async[^]*?};\n\n/m, '');

conv = conv.replace(
  /afterEach\(async \(\) => \{\n  for \(const client of clients\.splice\(0\)\) client\.terminate\(\);\n  for \(const hal of servers\.splice\(0\)\) \{\n    const \{wss\} = hal;\n    await eventually\(\(\) => wss\.clients\.size === 0\);\n    await hal\.stop\(\);\n  \}\n  setLogger\(\);\n\}\);/m,
  'afterEach(async () => {\n  await drainAndStop(clients, servers);\n  setLogger();\n});'
);

conv = conv.replace(/\/\/ A store with only the five required members.*?\nconst delegatingTo = [^]*?}\);\n\n/m, '');
conv = conv.replace(/delegatingTo/g, 'delegatingStore');

fs.writeFileSync('src/transport/conversationList.acceptance.test.ts', conv);

EOF
node fix_resume.mjs
